                throw new RateConflictException();
            }
        } else {
            rate.setRate(value);
            rate.setToDate(to);
            rate = rates.saveAndFlush(rate);
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + grade + " rate=" + rate.getRate().toPlainString()
                + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(sheetId, user, before);
        return rate;
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
    }
}
import { Component, inject, signal } from '@angular/core';
import { GRADES } from '../../core/people';
import { Rates } from '../../core/rates';

// The sheet's rates for each grade: one form sets a grade's rate from a date (or from the beginning
// of time) through a to-date (or for good), one table shows each grade's rate in force on the sheet's today, or n/a when none
